package org.dromara.warehouse.transfer.service.impl;
import org.dromara.common.core.constant.SystemConstants;import org.dromara.common.core.exception.ServiceException;import org.dromara.common.satoken.utils.LoginHelper;import org.dromara.property.api.ProjectReferenceService;import org.dromara.warehouse.inventory.mapper.InventoryMapper;import org.dromara.warehouse.inventory.service.InventoryMutationService;import org.dromara.warehouse.location.domain.WarehouseLocation;import org.dromara.warehouse.location.mapper.WarehouseLocationMapper;import org.dromara.warehouse.material.domain.Material;import org.dromara.warehouse.material.mapper.MaterialMapper;import org.dromara.warehouse.security.WarehouseAccessService;import org.dromara.warehouse.transfer.domain.*;import org.dromara.warehouse.transfer.domain.bo.TransferOrderBo;import org.dromara.warehouse.transfer.mapper.*;import org.dromara.warehouse.unit.domain.Unit;import org.dromara.warehouse.unit.mapper.UnitMapper;import org.dromara.warehouse.warehouse.domain.Warehouse;import org.dromara.warehouse.zone.domain.WarehouseZone;import org.dromara.warehouse.zone.mapper.WarehouseZoneMapper;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.List;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class TransferOrderServiceImplTest {@Mock TransferOrderMapper orderMapper;@Mock TransferOrderItemMapper itemMapper;@Mock WarehouseAccessService accessService;@Mock WarehouseLocationMapper locationMapper;@Mock WarehouseZoneMapper zoneMapper;@Mock MaterialMapper materialMapper;@Mock UnitMapper unitMapper;@Mock InventoryMapper inventoryMapper;@Mock InventoryMutationService mutationService;@Mock ProjectReferenceService projectReferenceService;@InjectMocks TransferOrderServiceImpl service;
 @Test void detailRequiresBothWarehousePermissions(){TransferOrder o=order("DRAFT");when(orderMapper.selectById(1L)).thenReturn(o);when(accessService.requireWarehouse(2L)).thenReturn(new Warehouse());doThrow(new ServiceException("denied")).when(accessService).requireWarehouse(3L);assertThrows(ServiceException.class,()->service.queryById(1L));verify(orderMapper,never()).selectTransferById(anyLong());}
 @Test void repeatedCompleteFailsBeforeMutation(){TransferOrder o=order("COMPLETED");when(orderMapper.selectForUpdate(1L)).thenReturn(o);when(accessService.requireEnabledWarehouse(anyLong())).thenReturn(warehouse(9L));assertThrows(ServiceException.class,()->service.complete(1L));verifyNoInteractions(mutationService);}
 @Test void crossCompanyCreateRejected(){TransferOrderBo bo=new TransferOrderBo();bo.setSourceWarehouseId(2L);bo.setTargetWarehouseId(3L);bo.setTransferType("NORMAL");when(accessService.requireEnabledWarehouse(2L)).thenReturn(warehouse(9L));when(accessService.requireEnabledWarehouse(3L)).thenReturn(warehouse(10L));assertThrows(ServiceException.class,()->service.create(bo));verify(orderMapper,never()).insert(any(TransferOrder.class));}
 @Test void completedCannotCancel(){TransferOrder o=order("COMPLETED");when(orderMapper.selectForUpdate(1L)).thenReturn(o);assertThrows(ServiceException.class,()->service.cancel(1L));verify(orderMapper,never()).cancelCas(anyLong());}
 @Test void completeHasTransactionBoundary()throws Exception{assertNotNull(TransferOrderServiceImpl.class.getMethod("complete",Long.class).getAnnotation(Transactional.class));}
 @Test void transferInFailureLeavesOrderUncompletedForTransactionRollback(){TransferOrder o=order("CONFIRMED");o.setTransferNo("DB1");when(orderMapper.selectForUpdate(1L)).thenReturn(o);Warehouse source=warehouse(9L);source.setId(2L);Warehouse target=warehouse(9L);target.setId(3L);when(accessService.requireEnabledWarehouse(2L)).thenReturn(source);when(accessService.requireEnabledWarehouse(3L)).thenReturn(target);TransferOrderItem i=new TransferOrderItem();i.setMaterialId(4L);i.setSourceLocationId(5L);i.setTargetLocationId(6L);i.setUnitId(7L);i.setQuantity(BigDecimal.ONE);when(itemMapper.selectByOrderId(1L)).thenReturn(List.of(i));WarehouseLocation sl=location(2L,8L);WarehouseLocation tl=location(3L,9L);when(locationMapper.selectById(5L)).thenReturn(sl);when(locationMapper.selectById(6L)).thenReturn(tl);when(zoneMapper.selectById(8L)).thenReturn(zone(2L));when(zoneMapper.selectById(9L)).thenReturn(zone(3L));Material m=new Material();m.setCompanyId(9L);m.setBaseUnitId(7L);m.setStatus(SystemConstants.NORMAL);when(materialMapper.selectById(4L)).thenReturn(m);Unit u=new Unit();u.setStatus(SystemConstants.NORMAL);u.setPrecisionScale(6);when(unitMapper.selectById(7L)).thenReturn(u);doThrow(new ServiceException("target failed")).when(mutationService).transferIn(eq(3L),eq(6L),eq(4L),any(),eq(1L),eq("DB1"),any(),eq(11L));try(MockedStatic<LoginHelper> login=mockStatic(LoginHelper.class)){login.when(LoginHelper::getUserId).thenReturn(11L);assertThrows(ServiceException.class,()->service.complete(1L));}verify(mutationService).transferOut(eq(2L),eq(5L),eq(4L),any(),eq(1L),eq("DB1"),any(),eq(11L));verify(orderMapper,never()).updateStatusCas(anyLong(),anyString(),eq("COMPLETED"),any(),any(),anyLong());}
 private TransferOrder order(String status){TransferOrder o=new TransferOrder();o.setId(1L);o.setSourceWarehouseId(2L);o.setTargetWarehouseId(3L);o.setStatus(status);return o;}private Warehouse warehouse(Long company){Warehouse w=new Warehouse();w.setCompanyId(company);return w;}private WarehouseLocation location(Long warehouse,Long zone){WarehouseLocation l=new WarehouseLocation();l.setWarehouseId(warehouse);l.setZoneId(zone);l.setStatus(SystemConstants.NORMAL);return l;}private WarehouseZone zone(Long warehouse){WarehouseZone z=new WarehouseZone();z.setWarehouseId(warehouse);z.setStatus(SystemConstants.NORMAL);return z;}}
